package com.campusiq.platform.client; import org.junit.jupiter.api.Test; import static org.assertj.core.api.Assertions.*; class CodeChefClientTest {@Test void parsesProfileHtml(){var c=new CodeChefClient(org.springframework.web.client.RestClient.builder(),"https://example.test");var p=c.parse("<div class='rating-number'>1800</div>Global Rank 1,234 Country Rank 99 Total Problems Solved 50");assertThat(p.rating()).isEqualTo(1800);assertThat(p.globalRank()).isEqualTo(1234);assertThat(p.totalSolved()).isEqualTo(50);}@Test void rejectsUnexpectedHtml(){var c=new CodeChefClient(org.springframework.web.client.RestClient.builder(),"https://example.test");assertThatThrownBy(()->c.parse("<html>no profile</html>")).isInstanceOf(PlatformClientException.class);}}
